/** @type {import('tailwindcss').Config} */
// Colours resolve to CSS variables defined in src/theme/palette.css (generated by
// scripts/generate-theme.mjs). Backgrounds, text and borders use separate scales so each
// theme can keep surfaces dark and text readable with the same class names.
const STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const PALETTES = ['slate', 'red', 'amber', 'emerald', 'blue', 'purple'];
// Palettes the code uses sparingly are folded onto the nearest themed palette.
const ALIASES = { gray: 'slate', green: 'emerald', yellow: 'amber', indigo: 'blue' };

const v = (name) => `rgb(var(--${name}) / <alpha-value>)`;

function scales(role) {
  const out = {};
  for (const p of PALETTES) out[p] = Object.fromEntries(STEPS.map((s) => [s, v(`${role}-${p}-${s}`)]));
  for (const [alias, target] of Object.entries(ALIASES)) out[alias] = out[target];
  return out;
}

const base = { inherit: 'inherit', current: 'currentColor', transparent: 'transparent', black: '#000' };

export default {
  content: ['./index.html', './src/**/*.{js,ts,jsx,tsx}'],
  theme: {
    colors: {
      ...base,
      ...scales('bg'),
      white: v('bg-white'),
      canvas: v('bg-canvas'),
      accent: { DEFAULT: v('bg-accent'), strong: v('bg-accent-strong'), soft: v('bg-accent-soft') },
    },
    textColor: {
      ...base,
      ...scales('text'),
      white: v('text-white'),
      accent: v('text-accent'),
    },
    borderColor: {
      ...base,
      ...scales('border'),
      DEFAULT: v('border-line'),
      white: v('border-white'),
      line: v('border-line'),
      accent: v('border-accent'),
    },
    ringColor: {
      ...base,
      ...scales('border'),
      DEFAULT: v('border-accent'),
      accent: v('border-accent'),
    },
    divideColor: {
      ...base,
      ...scales('border'),
      DEFAULT: v('border-line'),
      line: v('border-line'),
    },
    extend: {
      fontFamily: {
        sans: ['Inter', '"Segoe UI"', 'system-ui', '-apple-system', 'Roboto', '"Helvetica Neue"', 'Arial', 'sans-serif'],
        mono: ['"JetBrains Mono"', 'ui-monospace', 'SFMono-Regular', 'Menlo', 'Consolas', 'monospace'],
      },
      boxShadow: {
        panel: 'var(--shadow-panel)',
        raised: 'var(--shadow-raised)',
      },
    },
  },
  plugins: [],
};
